/**
 * Petshop Daugiau=Pigiau Display v1.0
 * Automatinis "vieneto kaina + sutaupote" info blokas pack produktams.
 * Skaiciuoja is bazinio produkto kainos ir pack kainos - veikia VISIEMS pack'ams.
 *
 * Rodo prie kainos zonos (po kaina, pries "I krepseli"):
 *   Pakuoteje: N vnt.
 *   Bendras kiekis: X kg/g (jei zinomas vieneto svoris)
 *   Vieneto kaina: Y EUR
 *   Iprastai po viena: Z EUR/vnt.
 *   Sutaupote: W EUR (P%)
 */

add_action('woocommerce_single_product_summary', function(){
  global $product;
  if (!$product) { $product = wc_get_product(get_the_ID()); }
  if (!$product) return;

  $base_id = $product->get_meta('_dp_base_product_id');
  if (!$base_id) return;
  $pack_qty = (int) $product->get_meta('_dp_pack_qty');
  if ($pack_qty <= 0) return;
  $base = wc_get_product($base_id);
  if (!$base) return;

  $base_unit = (float) $base->get_price();       // realiai galiojanti bazinio vnt. kaina
  $pack_price = (float) $product->get_price();
  if ($base_unit <= 0 || $pack_price <= 0) return;

  $pack_unit    = $pack_price / $pack_qty;
  $normal_total = $base_unit * $pack_qty;
  $savings      = $normal_total - $pack_price;
  $savings_pct  = $normal_total > 0 ? round($savings / $normal_total * 100) : 0;

  // Bendras kiekis rodomas TIK sausam maistui (bazinio pavadinime matas "kg").
  // Konservams/skanestams (g arba vnt.) - nerodom, uztenka "Pakuoteje: N vnt."
  $total_weight_html = '';
  if (preg_match('/(\d+(?:[.,]\d+)?)\s*kg\b/iu', $base->get_name(), $mm)) {
    $unit_kg = (float) str_replace(',', '.', $mm[1]);
    if ($unit_kg > 0) {
      $total = $unit_kg * $pack_qty;
      $total_str = rtrim(rtrim(number_format($total, 2, ',', ' '), '0'), ',');
      $total_weight_html = '<div class="dp-row"><span>Bendras kiekis:</span><strong>'.$total_str.' kg</strong></div>';
    }
  }

  echo '<div class="dp-savings-box">';
  echo '<div class="dp-row"><span>Pakuotėje:</span><strong>'.$pack_qty.' vnt.</strong></div>';
  echo $total_weight_html;
  echo '<div class="dp-row"><span>Vieneto kaina:</span><strong>'.wc_price($pack_unit).'</strong></div>';
  if ($savings > 0.005) {
    echo '<div class="dp-row dp-muted"><span>Įprastai po vieną:</span><span>'.wc_price($base_unit).'/vnt.</span></div>';
    echo '<div class="dp-row dp-save"><span>Sutaupote:</span><strong>'.wc_price($savings).' ('.$savings_pct.'%)</strong></div>';
  }
  echo '</div>';

  echo '<style>
    .dp-savings-box{margin:14px 0 18px;padding:14px 16px;background:#f6f8f7;border:1px solid #e0e6e3;border-radius:8px;max-width:340px}
    .dp-savings-box .dp-row{display:flex;justify-content:space-between;align-items:baseline;padding:3px 0;font-size:14px;line-height:1.5}
    .dp-savings-box .dp-row span:first-child{color:#555}
    .dp-savings-box .dp-row strong{color:#222;font-weight:600}
    .dp-savings-box .dp-muted{font-size:12px;color:#999;border-top:1px dashed #d5ddd9;margin-top:4px;padding-top:6px}
    .dp-savings-box .dp-muted span{color:#999 !important}
    .dp-savings-box .dp-save{margin-top:2px}
    .dp-savings-box .dp-save span:first-child{color:#2f5f46;font-weight:600}
    .dp-savings-box .dp-save strong{color:#2f5f46;font-size:15px}
    .dp-savings-box .dp-save strong .amount{color:#2f5f46}
  </style>';
}, 11);

